import java.util.ArrayList;
import java.util.List;

class Solution {
    public int sumNumbers(TreeNode root) {
        List<Integer> numbers = new ArrayList<>();
        collect(root, 0, numbers);
        int total = 0;
        for (int number : numbers) {
            total += number;
        }
        return total;
    }

    private void collect(TreeNode node, int prefix, List<Integer> numbers) {
        if (node == null) {
            return;
        }
        int value = prefix * 10 + node.val;
        if (node.left == null && node.right == null) {
            numbers.add(value);
            return;
        }
        collect(node.left, value, numbers);
        collect(node.right, value, numbers);
    }
}

